import { INCIDENT_PUBLIC_REPORT_PERMISSIONS as P } from '../constants/incidentPublicReportPermissionCodes';
import { hasPermissionCode, readCachedPackageCodes } from '../utils/medicalPermissionCode';
import { getAuthUser } from '@linm-soft-org/linm-web-common-components';
import { isPermissionsLocalModeActive } from '../dev/isPermissionsLocalMode';

const FULL_PACKAGES = ['ADMIN', 'MANAGER', 'MANAGER-UBNA'] as const;

function hasFullAccess(): boolean {
  if (isPermissionsLocalModeActive()) return true;
  const role = getAuthUser()?.role?.toLowerCase();
  if (role === 'admin' || role === 'manager') return true;
  return readCachedPackageCodes().some((code) =>
    FULL_PACKAGES.some((p) => p.localeCompare(code, undefined, { sensitivity: 'accent' }) === 0),
  );
}

export function useIncidentPublicReportPermissions() {
  const full = hasFullAccess();
  return {
    canRead: full || hasPermissionCode(P.read),
    canConfirm: full || hasPermissionCode(P.confirm),
    canReject: full || hasPermissionCode(P.reject),
    canPrint: full || hasPermissionCode(P.print),
    canDelete: full || hasPermissionCode(P.delete) || hasPermissionCode(P.confirm),
    isFullAccess: full,
  };
}
