import type { IncidentPublicReportPoster } from '../../models/IncidentPublicReport';

export function publicReportAbsoluteUrl(poster: IncidentPublicReportPoster): string {
  return `${window.location.origin}${poster.path}`;
}

export function publicReportQrImageUrl(absoluteUrl: string, size = 280): string {
  return `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(absoluteUrl)}`;
}

export function printPublicReportPoster(
  poster: IncidentPublicReportPoster,
  labels: { title: string; hint: string },
): void {
  const url = publicReportAbsoluteUrl(poster);
  const qr = publicReportQrImageUrl(url, 360);
  const html = buildPosterHtml(poster.companyName, url, qr, labels);
  const win = window.open('', '_blank', 'width=800,height=1000');
  if (!win) {
    printViaHiddenIframe(html);
    return;
  }
  writeAndPrint(win.document, win, html);
}

function buildPosterHtml(
  companyName: string,
  url: string,
  qr: string,
  labels: { title: string; hint: string },
): string {
  return `<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>${escapeHtml(labels.title)}</title>
<style>
  @page { size: A4; margin: 18mm; }
  body { font-family: sans-serif; text-align: center; color: #1a1a1a; }
  h1 { font-size: 28px; margin: 0 0 8px; }
  .company { font-size: 20px; font-weight: 600; margin-bottom: 24px; }
  img { width: 360px; height: 360px; }
  .hint { font-size: 16px; margin-top: 24px; }
  .url { font-size: 13px; margin-top: 16px; word-break: break-all; }
</style></head><body>
  <h1>${escapeHtml(labels.title)}</h1>
  <div class="company">${escapeHtml(companyName)}</div>
  <img src="${qr}" alt="" />
  <p class="hint">${escapeHtml(labels.hint)}</p>
  <p class="url">${escapeHtml(url)}</p>
</body></html>`;
}

function writeAndPrint(doc: Document, win: Window, html: string): void {
  doc.open();
  doc.write(html);
  doc.close();
  const img = doc.querySelector('img');
  let printed = false;
  const run = () => {
    if (printed) return;
    printed = true;
    try {
      win.focus();
      win.print();
    } catch {
      /* print dialog may be blocked */
    }
  };
  if (img && !img.complete) {
    img.addEventListener('load', run, { once: true });
    img.addEventListener('error', run, { once: true });
    window.setTimeout(run, 1500);
  } else {
    window.setTimeout(run, 50);
  }
}

function printViaHiddenIframe(html: string): void {
  const iframe = document.createElement('iframe');
  iframe.setAttribute('aria-hidden', 'true');
  iframe.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;';
  document.body.appendChild(iframe);
  const doc = iframe.contentDocument;
  const win = iframe.contentWindow;
  if (!doc || !win) {
    iframe.remove();
    return;
  }
  writeAndPrint(doc, win, html);
  window.setTimeout(() => iframe.remove(), 60_000);
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
